// Run against `go run ./testdata/browser`. Playwright is a test-only dependency.
const assert=require('node:assert/strict');
const {chromium}=require(process.env.GATEWAY_PLAYWRIGHT||'playwright');
(async()=>{
 const admin=process.env.GATEWAY_BROWSER_ADMIN,fixtures=process.env.GATEWAY_BROWSER_FIXTURES;
 if(!admin||!fixtures)throw Error('Set GATEWAY_BROWSER_ADMIN and GATEWAY_BROWSER_FIXTURES from the fixture output');
 const browser=await chromium.launch({headless:true,...(process.env.GATEWAY_BROWSER_CHROME?{executablePath:process.env.GATEWAY_BROWSER_CHROME}:{})});
 try{
 const page=await browser.newPage({viewport:{width:1440,height:1000}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
 // LAN HTTP does not expose randomUUID; exercising without it also verifies the fallback.
 await page.addInitScript(()=>Object.defineProperty(Crypto.prototype,'randomUUID',{value:undefined,configurable:true}));
 const data=await(await page.request.get(fixtures)).json();
 const steps=[];const pass=name=>{steps.push(name);console.log('PASS '+name)};
 async function fill(selector,value){await page.locator(selector).fill(String(value));await page.locator(selector).dispatchEvent('change')}
 async function confirm(){await page.locator('#acceptConfirm').click()}
 async function action(button,path){const response=page.waitForResponse(r=>r.url()===admin+'/api/'+path&&r.request().method()==='POST');await page.locator(button).click();const result=await response;assert.equal(result.status(),200,await result.text());return result.json()}
 async function publish(){const tab=await page.locator('[data-tab].active').getAttribute('data-tab');await page.locator('#publishHost').click();const refreshed=page.waitForResponse(r=>r.url()===admin+'/api/hosts'&&r.request().method()==='GET');const result=await action('#acceptConfirm','publish');await page.locator('#editor').waitFor({state:'hidden'});await page.locator('#toast').filter({hasText:'发布成功'}).waitFor();await refreshed;await page.locator('[data-edit]').first().click();await page.locator(`[data-tab="${tab}"]`).click();return result}
 async function business(path,options={}){return page.request.fetch(data.business+path,{...options,headers:{Host:'browser.test',...options.headers},maxRedirects:0})}
 await page.goto(admin);await page.locator('#loginForm').waitFor();assert.equal(await page.locator('#loginName').count(),0);
 await fill('#loginPassword','browser-admin-password');await page.locator('#loginForm button').click();await page.locator('#loginError').filter({hasText:'not set'}).waitFor();assert.equal((await page.request.get(admin+'/api/hosts')).status(),401);pass('未初始化页面与管理 API 锁定');
 await page.request.post(fixtures+'/password');await page.locator('#loginForm button').click();await page.locator('#newHost').waitFor();pass('命令设置密码后登录');
 await page.locator('#newHost').click();assert.equal(await page.locator('#hostName').count(),0);await fill('#hostDomains','browser.test');await page.locator('#forceHTTPS').uncheck();
 async function route(index,type,path,to){await page.locator(`[data-tab="${type}"]`).click();await page.locator('#addRoute').click();await fill(`[data-route="${index}"][data-field="path"]`,path);await fill(`[data-route="${index}"][data-field="to"]`,to)}
 await route(0,'proxy','/api/*',data.upstream+'/up/*');await route(1,'rewrite','/old/*','/api/*');await route(2,'redirect','/redirect','https://example.test/target');await route(3,'static','/files',data.staticDir);
 const initialHeight=await page.locator('#editor').evaluate(node=>node.getBoundingClientRect().height);for(const tab of ['config','proxy','rewrite','redirect','static','limits','history']){await page.locator(`[data-tab="${tab}"]`).click();const height=await page.locator('#editor').evaluate(node=>node.getBoundingClientRect().height);assert.ok(Math.abs(height-initialHeight)<1)}pass('独立路由标签页与固定高度弹窗');
 const draft=await action('#saveDraft','draft');assert.equal((await business('/api/hello')).status(),404);pass('四类规则保存草稿不生效');
 const published=await publish();assert.equal(published.version,1);assert.equal(published.draft.name,'browser.test');assert.equal(await page.locator('[data-field="authLevel"]').count(),0);assert.equal(published.draft.proxies[0].authLevel,0);
 assert.equal(await(await business('/api/hello?q=1',{method:'POST',data:'stream-body'})).text(),'POST /up/hello?q=1 stream-body');
 assert.equal(await(await business('/old/hello')).text(),'GET /up/hello ');assert.equal((await business('/redirect')).headers().location,'https://example.test/target');assert.equal(await(await business('/files/hello.txt')).text(),'browser-static');pass('发布后代理/改写/重定向/静态实际请求');
 if(process.env.GATEWAY_BROWSER_ARTIFACTS){require('node:fs').mkdirSync(process.env.GATEWAY_BROWSER_ARTIFACTS,{recursive:true});await page.locator('#closeEditor').click();await page.screenshot({path:process.env.GATEWAY_BROWSER_ARTIFACTS+'/gateway-hosts.png',fullPage:true});await page.locator('[data-edit]').first().click()}

 await page.locator('#previewHost').click();await fill('#previewPath','/old/hello');await page.locator('#previewForm button').click();await page.locator('#previewResult').filter({hasText:'proxy'}).waitFor();await page.locator('#closePreview').click();pass('路由预览');
 await page.locator('[data-tab="limits"]').click();await page.locator('#addLimit').click();assert.equal(await page.locator('[data-count-mode="0"]').inputValue(),'total');await fill('[data-limit="0"][data-field="requests"]',2);await fill('[data-limit="0"][data-field="periodSeconds"]',60);await page.locator('[data-add-condition="0"]').click();await fill('[data-rule="0"][data-condition="0"][data-field="value"]','/api/limited');
 await page.locator('[data-count-mode="0"]').selectOption('ip');for(const source of ['host','path','ua','header','session','cookie']){await page.locator('[data-add-dimension="0"]').click();const index=await page.locator('[data-dimension][data-field="source"]').count()-1;await page.locator(`[data-dimension="${index}"][data-field="source"]`).selectOption(source);if(['header','cookie'].includes(source))await fill(`[data-dimension="${index}"][data-field="name"]`,source==='header'?'X-Account':'account')}
 if(process.env.GATEWAY_BROWSER_ARTIFACTS)await page.screenshot({path:process.env.GATEWAY_BROWSER_ARTIFACTS+'/gateway-limits.png',fullPage:true});await publish();const quotaHeaders={'User-Agent':'browser-acceptance','X-Account':'one','Session-ID':'browser-session',Cookie:'account=one'};
 assert.equal((await business('/api/limited',{headers:quotaHeaders})).status(),200);assert.equal((await business('/api/limited',{headers:quotaHeaders})).status(),200);const denied=await business('/api/limited',{headers:quotaHeaders});assert.equal(denied.status(),429);assert.ok(denied.headers()['retry-after']);assert.equal((await business('/api/limited',{headers:{...quotaHeaders,'X-Account':'two'}})).status(),200);pass('七维联合限流与429/Retry-After');
 await page.locator('[data-limit="0"][data-field="mode"]').selectOption('observe');await publish();for(let i=0;i<3;i++)assert.equal((await business('/api/limited',{headers:quotaHeaders})).status(),200);pass('观察模式');
 await page.locator('[data-tab="history"]').click();await page.locator('[data-rollback="1"]').click();await action('#acceptConfirm','rollback');await page.locator('#editor').waitFor({state:'hidden'});await page.locator('[data-edit]').first().click();await page.locator('[data-tab="limits"]').click();assert.equal(await page.locator('.limit-card').count(),0);pass('历史回滚');
 await page.locator('#closeEditor').click();await page.locator('[data-page="certificates"]').click();assert.equal(await page.locator('#libraryName').count(),0);await page.locator('#libraryCertificateFile').setInputFiles({name:'certificate.pem',mimeType:'application/x-pem-file',buffer:Buffer.from(data.certificate)});await page.locator('#libraryKeyFile').setInputFiles({name:'private.key',mimeType:'application/x-pem-file',buffer:Buffer.from(data.key)});const uploaded=await action('#libraryForm button.primary','certificates/save');assert.ok(!JSON.stringify(uploaded).includes('PRIVATE KEY'));assert.equal(uploaded.name,'browser.test');await page.locator('#certificateRows').filter({hasText:'有效'}).waitFor();pass('独立证书库上传与即时匹配');await fill('#acmeEmail','browser@example.test');await action('#acmeForm button','acme');pass('页面设置自动签发，无需编辑 YAML');
 await page.locator('[data-page="hosts"]').click();await page.locator('[data-edit]').first().click();await page.locator('#domainCertificates').filter({hasText:'HTTPS'}).waitFor();await page.locator('#forceHTTPS').check();await publish();assert.equal((await business('/api/hello')).status(),308);assert.equal((await business('/api/hello')).headers().location,'https://browser.test:10443/api/hello');await page.locator('#forceHTTPS').uncheck();await publish();assert.equal((await business('/api/hello')).status(),200);pass('自适应 HTTPS 与可关闭的默认跳转');
 await page.locator('#closeEditor').click();await page.locator('[data-page="certificates"]').click();await page.locator('[data-edit-certificate]').first().click();await action('#libraryForm button.primary','certificates/save');await page.locator('#certificateRows').filter({hasText:'browser.test'}).waitFor();await page.locator('[data-delete-certificate]').first().click();await action('#acceptConfirm','certificates/delete');await page.locator('#certificateRows').filter({hasText:'尚无证书'}).waitFor();await page.locator('[data-page="hosts"]').click();await page.locator('[data-edit]').first().click();await page.locator('#domainCertificates').filter({hasText:'尚无有效证书'}).waitFor();assert.equal((await business('/api/hello')).status(),200);pass('证书编辑/删除与自动 HTTP 回退');

 await page.locator('#closeEditor').click();const downloadPromise=page.waitForEvent('download');await page.locator('#export').click();const download=await downloadPromise;const fs=require('node:fs');const exported=JSON.parse(fs.readFileSync(await download.path(),'utf8'));assert.equal(exported.length,1);assert.ok(exported.every(record=>[record.draft,record.current,...(record.history||[]).map(item=>item.host)].filter(Boolean).every(host=>!host.https?.sealedKey)));await page.locator('#importFile').setInputFiles({name:'hosts.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(exported))});await page.locator('#toast').filter({hasText:'已导入'}).waitFor();pass('导出脱敏与导入草稿');
 await page.locator('[data-page="events"]').click();await page.locator('#eventRows').filter({hasText:'limit'}).waitFor();await page.locator('[data-page="settings"]').click();await page.locator('#settingsList').filter({hasText:'管理地址'}).waitFor();assert.equal(await page.locator('#userForm').count(),0);pass('事件/节点/设置与移除多账号');
 await page.locator('[data-page="hosts"]').click();await page.locator('[data-edit]').first().click();await fill('#hostDomains','invalid domain');await page.locator('#saveDraft').click();await page.locator('#toast').filter({hasText:'domain'}).waitFor();assert.equal((await business('/api/hello')).status(),200);pass('错误配置不影响流量');await fill('#hostDomains','browser.test');
 // A second tab publishes a newer draft; the first tab must report conflict.
 const other=await browser.newPage();await other.goto(admin); // separate page shares the default context cookies
 // Authenticate explicitly because browser.newPage creates an isolated context.
 await other.locator('#loginPassword').fill('browser-admin-password');await other.locator('#loginForm button').click();await other.locator('[data-edit]').first().click();await other.locator('#hostDomains').fill('browser.test, concurrent.browser.test');await other.locator('#saveDraft').click();await other.locator('#toast').filter({hasText:'草稿已保存'}).waitFor();
 await page.locator('#saveDraft').click();await page.locator('#toast').filter({hasText:'configuration changed'}).waitFor();pass('并发编辑冲突');await other.close();await page.locator('#closeEditor').click();await page.locator('[data-page="hosts"]').click();
 await page.locator('[data-edit]').first().click();await page.locator('#hostEnabled').uncheck();await publish();assert.equal((await business('/api/hello')).status(),503);await page.locator('#hostEnabled').check();await publish();assert.equal((await business('/api/hello')).status(),200);pass('停用/启用');
 await page.locator('#deleteHost').click();await action('#acceptConfirm','delete');assert.equal((await business('/api/hello')).status(),404);pass('删除 Host');
 await page.request.post(fixtures+'/reset-password');await page.locator('[data-page="settings"]').click();await page.locator('#loginForm').waitFor();await fill('#loginPassword','browser-new-password');await page.locator('#loginForm button').click();await page.locator('#newHost').waitFor();pass('命令修改密码与撤销旧会话');
 await page.setViewportSize({width:390,height:844});assert.ok(await page.locator('#newHost').isVisible());pass('移动布局');await page.locator('#logout').click();await page.locator('#loginForm').waitFor();pass('退出');
 assert.deepEqual(errors,[]);console.log(JSON.stringify({passed:steps,errors},null,2));
 } finally {await browser.close()}
})().catch(error=>{console.error(error);process.exitCode=1});
